class Solution:
    def fourSum(self, nums: List[int], target: int) -> List[List[int]]:
        nums.sort()
        res = []
        def kSum(k, start, target, path):
            if k == 2:
                l, r = start, len(nums)-1
                while l < r:
                    s = nums[l] + nums[r]
                    if s == target:
                        res.append(path + [nums[l], nums[r]])
                        l += 1
                        while l < r and nums[l] == nums[l-1]:
                            l += 1
                    elif s < target:
                        l += 1
                    else:
                        r -= 1
                return
            for i in range(start, len(nums)-k+1):
                if i > start and nums[i] == nums[i-1]:
                    continue
                kSum(k-1, i+1, target-nums[i], path+[nums[i]])
        kSum(4, 0, target, [])
        return res

reference_solution.javascript:
function fourSum(nums, target) {
    nums.sort((a,b) => a-b);
    const res = [];
    function kSum(k, start, target, path) {
        if (k === 2) {
            let l = start, r = nums.length-1;
            while (l < r) {
                const s = nums[l] + nums[r];
                if (s === target) {
                    res.push([...path, nums[l], nums[r]]);
                    l++;
                    while (l < r && nums[l] === nums[l-1]) l++;
                } else if (s < target) l++;
                else r--;
            }
            return;
        }
        for (let i = start; i < nums.length-k+1; i++) {
            if (i > start && nums[i] === nums[i-1]) continue;
            kSum(k-1, i+1, target-nums[i], [...path, nums[i]]);
        }
    }
    kSum(4, 0, target, []);
    return res;
}
